/** Real API integration for intake, workstation, survey, report and Admin. */
const assert=require('node:assert/strict');
const fs=require('node:fs'),path=require('node:path');
const {chromium}=require('playwright-core');
const base=process.env.E2E_BASE_URL||'http://127.0.0.1:8027';
const out=path.resolve(__dirname,'../artifacts/six-modules');
fs.mkdirSync(out,{recursive:true});
async function main(){
 const browser=await chromium.launch({headless:true,executablePath:'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe'});
 const page=await browser.newPage({viewport:{width:1440,height:900}}),errors=[],checks=[];
 page.on('pageerror',e=>errors.push(e.message));
 page.on('console',m=>{if(m.type()==='error')errors.push({message:m.text(),location:m.location()});});
 let studyId,token;
 const pass=x=>{checks.push(x);console.log('PASS '+x);};
 try{
  await page.goto(base+'/#new_case');
  await page.locator('#loginUsername').fill('doctor');
  await page.locator('#loginPassword').fill(process.env.APP_DOCTOR_PASSWORD||'doctor-local-test-2026');
  await page.locator('#loginSubmit').click();
  await page.waitForFunction(()=>document.querySelector('#demoSamples button[data-ready=true]'));
  assert.equal(await page.locator('#adminNav').isVisible(),false);
  await page.locator('#demoSamples button').first().click();
  await page.waitForFunction(()=>currentSelectedFile&&!currentCase.selecting&&!demoSelecting&&!document.getElementById('runSegmentationBtn').disabled);
  const pid='BN-E2E-'+Date.now();
  await page.locator('#intakePid').fill(pid);
  await page.locator('input[name=ovarySide][value=LEFT]').check();
  await page.locator('#intakeReason').selectOption({label:'Theo dõi u nang'});
  await page.locator('#runSegmentationBtn').click();
  await page.locator('#screenResults').waitFor({state:'visible',timeout:120000});
  await page.waitForFunction(()=>currentMeasurements!==null);
  studyId=await page.evaluate(()=>currentCase.study_id);
  token=await page.evaluate(()=>sessionStorage.getItem('ovarian_ai_access_token'));
  const auth={Authorization:'Bearer '+token};
  let response=await page.request.get(base+'/api/cases/'+studyId,{headers:auth}),study=await response.json();
  assert.equal(study.patient_id,pid);assert.equal(study.ovary_side,'LEFT');assert.equal(study.clinical_indication,'Theo dõi u nang');
  const measurement=await page.evaluate(()=>currentMeasurements);
  assert.equal(measurement.calibrated,false);assert.equal(measurement.max_diameter_mm,null);
  assert.match(await page.locator('#measurementDmax').textContent(),/px/);
  assert.match(await page.locator('#calibrationBadge').textContent(),/pixel/);
  pass('Real demo image, intake metadata persistence and source-pixel calibration guard');
  const savedRle=await page.evaluate(()=>encodeCurrentMask());
  const raster=()=>page.evaluate(()=>ctx.getImageData(0,0,512,512).data.reduce((sum,v)=>sum+v,0));
  await page.locator('[data-view=original]').click();const before=await raster();
  await page.locator('#brightnessSlider').fill('150');await page.locator('#contrastSlider').fill('175');
  assert.notEqual(await raster(),before);assert.deepEqual(await page.evaluate(()=>encodeCurrentMask()),savedRle);
  await page.evaluate(()=>resetImageAdjustments());assert.equal(await raster(),before);
  await page.locator('[data-view=overlay]').click();
  await page.locator('#canvasContainer').focus();await page.keyboard.press('b');await page.keyboard.press(']');
  assert.equal(await page.evaluate(()=>brushSize),18);await page.keyboard.press('[');
  await page.locator('[data-comparison=side]').click();
  await page.evaluate(()=>zoomInCanvas());
  assert.deepEqual(await page.evaluate(()=>[canvas.style.transform,document.getElementById('comparisonOriginalCanvas').style.transform]).then(x=>x[0]===x[1]),true);
  await page.evaluate(()=>resetZoomCanvas());
  const point=await page.evaluate(()=>{
   const pixels=maskCtx.getImageData(0,0,512,512).data;
   for(let y=120;y<390;y+=15)for(let x=120;x<390;x+=15)if(!pixels[(y*512+x)*4+3])return{x,y};
   throw Error('No editable background');
  });
  const box=await page.locator('#editorCanvas').boundingBox(),x=box.x+point.x*box.width/512,y=box.y+point.y*box.height/512;
  await page.mouse.move(x,y);
  assert.equal(await page.locator('#brushCursor').isVisible(),true);
  const ring=await page.locator('#brushCursor').boundingBox();
  assert.ok(Math.abs(ring.width-16*box.width/512)<1);
  await page.mouse.down();await page.mouse.move(x+4,y+4);await page.mouse.up();
  const edited=await page.evaluate(()=>encodeCurrentMask());assert.notDeepEqual(edited,savedRle);
  await page.locator('#canvasContainer').focus();await page.keyboard.press('Control+z');
  assert.deepEqual(await page.evaluate(()=>encodeCurrentMask()),savedRle);
  await page.keyboard.press('Control+y');assert.deepEqual(await page.evaluate(()=>encodeCurrentMask()),edited);
  await page.locator('[data-comparison=curtain]').click();
  await page.locator('#curtainSlider').fill('100');const original=await raster();
  await page.locator('#curtainSlider').fill('0');assert.notEqual(await raster(),original);
  await page.locator('#curtainHandle').focus();await page.keyboard.press('ArrowRight');
  assert.equal(await page.evaluate(()=>curtainPosition),2);
  await page.locator('#contourToggle').click();assert.deepEqual(await page.evaluate(()=>encodeCurrentMask()),edited);
  await page.locator('[data-comparison=single]').click();
  pass('Image-only adjustments, brush outline/shortcuts, Undo/Redo, synchronized comparison and curtain/contour');
  await page.locator('#reviewMorphology').fill('Mô tả ranh giới do người rà soát nhập');
  await page.locator('#textDoctorNotes').fill('E2E: reviewed segmentation boundary; no diagnosis.');
  await page.locator('#confirmSegmentationBtn').click();
  await page.locator('.hitl-survey summary').click();
  await page.locator('input[name=hitlRating][value="4"]').check();
  await page.locator('input[name=hitlIssue][value=NO_ERROR]').check();
  await page.locator('input[name=hitlIssue][value=BOUNDARY_MISMATCH]').check();
  assert.equal(await page.locator('input[name=hitlIssue][value=NO_ERROR]').isChecked(),false);
  await page.locator('#saveReviewBtn').focus();
  await page.keyboard.press('Space');
  await page.waitForFunction(()=>currentCase.confirmed===true);
  response=await page.request.get(base+'/api/cases/'+studyId,{headers:auth});study=await response.json();
  const review=study.images[0].review;
  assert.deepEqual(review.hitl_feedback,{usability_rating:4,issues:['BOUNDARY_MISMATCH']});
  assert.ok(review.time_spent_seconds>0);assert.equal(review.doctor_id,'doctor');
  assert.deepEqual(review.verified_mask_rle,edited);assert.ok(review.reviewed_at);
  pass('Optional survey persisted with exact edited mask, actual actor and review duration');
  await page.locator('#reportPreviewBtn').click();
  await page.waitForFunction(()=>!document.getElementById('reportPrintBtn').disabled,{timeout:30000});
  assert.equal(await page.locator('#reportPreviewError').isVisible(),false);
  assert.ok((await page.locator('#reportPreviewContent').textContent()).includes(pid));
  assert.ok((await page.locator('#reportPreviewContent').textContent()).includes('Chưa có chữ ký số'));
  assert.ok((await page.locator('#reportPreviewContent').textContent()).includes('Bản mẫu nghiên cứu - Không thay thế chẩn đoán y khoa'));
  const recordedModel=study.images[0].prediction.model_version;
  assert.ok(recordedModel);
  assert.ok((await page.locator('#reportPreviewContent').textContent()).includes(recordedModel));
  assert.equal(await page.locator('#reportPreviewContent .research-report-image img').count(),2);
  await page.locator('#reportFacility').selectOption('Times City');
  assert.match(await page.locator('[data-report-facility]').textContent(),/Times City/);
  await page.screenshot({path:path.join(out,'report-a4-preview.png'),fullPage:true});
  await page.evaluate(()=>{window.print=()=>{window.__printCalled=true;};});
  await page.locator('#reportPrintBtn').click();await page.waitForFunction(()=>window.__printCalled);
  await page.emulateMedia({media:'print'});
  assert.equal(await page.locator('.app-header').isVisible(),false);
  assert.equal(await page.locator('#researchReportPrintRoot').isVisible(),true);
  await page.pdf({path:path.join(out,'report-a4.pdf'),preferCSSPageSize:true,printBackground:true});
  await page.emulateMedia({media:'screen'});await page.evaluate(()=>window.dispatchEvent(new Event('afterprint')));
  await page.evaluate(()=>closeReportPreview());
  const event=page.waitForEvent('download');await page.locator('#exportOverlayBtn').click();
  const download=await event,downloadPath=path.join(out,'confirmed-overlay.png');await download.saveAs(downloadPath);
  const png=fs.readFileSync(downloadPath);assert.equal(png.readUInt32BE(16),measurement.source_dimensions[0]);assert.equal(png.readUInt32BE(20),measurement.source_dimensions[1]);
  pass('Full-source confirmed overlay export and actual report preview/A4 print isolating navigation');
  const sizes=[[1366,768],[1440,900],[1920,1080],[768,900],[390,844]];
  for(const [width,height]of sizes){
   await page.setViewportSize({width,height});await page.evaluate(()=>{document.activeElement?.blur();window.scrollTo(0,0);});
   await page.screenshot({path:path.join(out,'workspace-'+width+'.png'),fullPage:true});
   assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'No horizontal overflow '+width);
   assert.equal(await page.locator('#editorCanvas').isVisible(),true);
  }
  await page.setViewportSize({width:1440,height:900});
  await page.locator('[data-route=cases]').click();await page.locator('#caseSearch').fill(study.study_code);
  await page.waitForFunction(()=>document.querySelector('#casesTableBody button'));
  await page.locator('#casesTableBody button').first().click();await page.locator('#screenResults').waitFor({state:'visible'});
  assert.deepEqual(await page.evaluate(()=>getSurveyFeedback()),review.hitl_feedback);
  assert.equal(await page.locator('#reviewMorphology').inputValue(),review.lesion_type);
  assert.equal(await page.evaluate(()=>currentCase.confirmed),true);
  pass('Responsive required desktop sizes plus tablet/mobile and saved survey/morphology reopening');
  const denied=await page.request.get(base+'/api/admin/models',{headers:auth});assert.equal(denied.status(),403);
  await page.evaluate(()=>logout());
  await page.locator('#accountButton').click();await page.locator('#loginUsername').fill('admin');
  await page.locator('#loginPassword').fill(process.env.APP_ADMIN_PASSWORD||'admin-local-test-2026');
  await page.locator('#loginSubmit').click();await page.locator('#adminNav').waitFor({state:'visible'});
  await page.locator('#adminNav').click();
  await page.waitForFunction(()=>document.querySelector('#adminModels .admin-model')&&document.querySelector('#adminLogsBody tr'));
  assert.ok((await page.locator('#adminModels').textContent()).includes('Mô hình chính'));
  const adminToken=await page.evaluate(()=>sessionStorage.getItem('ovarian_ai_access_token'));
  const telemetry=await (await page.request.get(base+'/api/admin/models',{headers:{Authorization:'Bearer '+adminToken}})).json();
  assert.ok(telemetry.registered_models.some(model=>model.is_loaded&&/^[a-f0-9]{64}$/.test(model.checksum)&&typeof model.threshold==='number'));
  assert.ok(telemetry.mean_inference_latency_ms>0);assert.ok(telemetry.latency_sample_count>0);
  assert.equal(telemetry.latency_scope,'all_recorded_predictions');
  await page.locator('#adminActorFilter').fill('doctor');
  assert.ok((await page.locator('#adminLogsBody').textContent()).includes('doctor'));
  await page.locator('#adminActionFilter').selectOption('DOCTOR_MODIFIED');
  assert.ok((await page.locator('#adminLogsBody').textContent()).includes('DOCTOR_MODIFIED'));
  await page.screenshot({path:path.join(out,'admin-1440.png'),fullPage:true});
  pass('Admin role navigation, protected API and actual model/audit filtering');
  assert.deepEqual(errors,[]);pass('Clean browser console and JavaScript runtime');
  fs.writeFileSync(path.join(out,'e2e-result.json'),JSON.stringify({passed:true,base,checks,errors},null,2));
 }catch(error){
  await page.screenshot({path:path.join(out,'failure.png'),fullPage:true});console.error(error.stack);
  fs.writeFileSync(path.join(out,'e2e-result.json'),JSON.stringify({passed:false,checks,errors,error:error.stack},null,2));process.exitCode=1;
 }finally{
  if(studyId){
   const login=await page.request.post(base+'/api/auth/login',{data:{username:'admin',password:process.env.APP_ADMIN_PASSWORD||'admin-local-test-2026'}});
   if(!login.ok())throw new Error('E2E cleanup requires an admin account');
   const adminToken=(await login.json()).access_token;
   const deleted=await page.request.delete(base+'/api/cases/'+studyId,{headers:{Authorization:'Bearer '+adminToken}});
   assert.equal(deleted.status(),200,'E2E case cleanup requires admin authorization');
  }
  await browser.close();
 }
}
main().catch(error=>{console.error(error);process.exitCode=1;});
